outputs.output:
{
  "title": "Does button B sell more?",
  "setting": "Day 3 at Aurora Shop",
  "mission": "Decide if **button B really sells more than button A** and tell {{product}} what to do next. Use a chance check and a large enough sample before you call a winner.",
  "deadline": "Meeting with {{product}} today at 3 p.m.",
  "panels": [
    {
      "title": "Checkout test · first day",
      "metrics": [
        {
          "label": "Button A sales",
          "value": "3.0%",
          "note": "30 sales from 1,000 visits"
        },
        {
          "label": "Button B sales",
          "value": "3.4%",
          "note": "34 sales from 1,000 visits"
        },
        {
          "label": "Visits per button",
          "value": "1,000",
          "note": "visitors split evenly"
        }
      ],
      "note": "Aurora Shop checkout test"
    }
  ],
  "team": [
    {
      "id": "data",
      "role": "Data analyst",
      "expertise": "Knows how to tell a real gap from chance and how large a sample needs to be.",
      "ai": false
    },
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Wants button B live for today's meeting and worries about lost sales.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Runs quick checks and calculations when asked, but does not make the call.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of a wrong call",
      "start": 45,
      "goodWhen": "low"
    },
    {
      "id": "patience",
      "label": "{{product}}'s patience",
      "start": 55,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "difference",
      "name": "Tell a real difference from chance",
      "practice": "Take two counts from today, such as sales for two buttons, and write one sentence on whether the gap could be chance."
    },
    {
      "id": "sample",
      "name": "Choose a sample size",
      "practice": "Write how many visits per button you would want for a small gap, and give one reason for that number."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain one test result to someone who is not a data person, in one sentence."
    }
  ],
  "startNodeId": "first-look",
  "nodes": [
    {
      "id": "first-look",
      "messages": [
        {
          "from": "product",
          "text": "Button B is at 3.4% and A is at 3.0%. Can we put B live for everyone before the 3 p.m. meeting?"
        },
        {
          "from": "data",
          "text": "That gap is only 4 more sales out of 1,000 visits. It could be chance, and we should check before we call it real."
        }
      ],
      "prompt": "What do you do first?",
      "choices": [
        {
          "id": "wait-day",
          "text": "Tell {{product}} to keep the test running for one more day first",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "One more day is fine, but I still need an answer for the 3 p.m. meeting."
            },
            {
              "from": "data",
              "text": "One more day adds about 1,000 visits each, so the counts will still be small for a gap this size."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Waiting a day helps, but it may still leave too few visits to trust a gap this small.",
              "example": "\"Let's agree on a target number of visits first, then check once.\""
            }
          ],
          "next": "sample-size"
        },
        {
          "id": "ask-ai",
          "text": "Ask {{ai}} to check if a gap this size could happen by chance",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "I checked 30 sales in 1,000 visits for A and 34 in 1,000 for B. The p-value is about 0.61, which means a gap this size could happen by chance quite often if B were no better than A."
            },
            {
              "from": "data",
              "text": "That is hypothesis testing in plain form: ask whether the gap is real or just chance. With this sample, we do not know yet."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -15
            },
            {
              "meter": "patience",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "difference",
              "kind": "good",
              "text": "You checked whether the gap could be chance before acting on it.",
              "example": null
            }
          ],
          "next": "sample-size"
        },
        {
          "id": "launch-now",
          "text": "Tell {{product}} to launch button B for everyone right away",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Great, I will put B live for everyone today."
            },
            {
              "from": "data",
              "text": "I am worried. A gap of 30 versus 34 sales could be chance, and we have not checked it yet."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 20
            },
            {
              "meter": "patience",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "difference",
              "kind": "improve",
              "text": "You treated a higher number as proof, even though 34 versus 30 sales could be chance.",
              "example": "\"Can we check if this gap could be chance before we launch?\""
            }
          ],
          "next": "last-check"
        }
      ]
    },
    {
      "id": "sample-size",
      "messages": [
        {
          "from": "data",
          "text": "With only 1,000 visits each, 30 versus 34 sales is a very small count. A bigger sample will make the gap easier to judge."
        },
        {
          "from": "product",
          "text": "I need an answer today. How long does a bigger sample really take?"
        }
      ],
      "prompt": "How much more data do you want before deciding?",
      "choices": [
        {
          "id": "decide-now",
          "text": "Decide now with the 1,000 visits each that we already have",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "Deciding now leaves the same small counts, so a chance gap could still look like a real one."
            },
            {
              "from": "product",
              "text": "Fast is good for the meeting, even if {{data}} is not happy about it."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 10
            },
            {
              "meter": "patience",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "You decided with the same small sample, so the risk of a wrong call stays high.",
              "example": "\"Let's get a larger sample before we call B the winner.\""
            }
          ],
          "next": "last-check"
        },
        {
          "id": "run-long",
          "text": "Keep the test running until each button has 10,000 visits",
          "quality": "strong",
          "replies": [
            {
              "from": "data",
              "text": "10,000 visits each will tell us much more. A real gap should hold up as the sample grows."
            },
            {
              "from": "product",
              "text": "One week is long, but I can tell the meeting we are running a bigger test."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "patience",
              "change": -15
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "Checkout test · larger sample",
              "metrics": [
                {
                  "label": "Button A sales",
                  "value": "3.0%",
                  "note": "300 sales from 10,000 visits"
                },
                {
                  "label": "Button B sales",
                  "value": "3.6%",
                  "note": "360 sales from 10,000 visits"
                },
                {
                  "label": "Visits per button",
                  "value": "10,000",
                  "note": "visitors split evenly"
                }
              ],
              "note": "Same test, more visits"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You chose a much larger sample, so a real gap would be easier to tell from chance.",
              "example": null
            }
          ],
          "next": "explain-result"
        },
        {
          "id": "run-short",
          "text": "Add one more day, then check again with about 2,000 visits each",
          "quality": "fair",
          "replies": [
            {
              "from": "data",
              "text": "That doubles the sample to 2,000 each, but 60 versus 68 sales can still be chance."
            },
            {
              "from": "product",
              "text": "One day is easier for the meeting, even if the answer is still not firm."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "patience",
              "change": -5
            }
          ],
          "timeJump": {
            "label": "One day later",
            "panel": {
              "title": "Checkout test · a little more data",
              "metrics": [
                {
                  "label": "Button A sales",
                  "value": "3.0%",
                  "note": "60 sales from 2,000 visits"
                },
                {
                  "label": "Button B sales",
                  "value": "3.4%",
                  "note": "68 sales from 2,000 visits"
                },
                {
                  "label": "Visits per button",
                  "value": "2,000",
                  "note": "visitors split evenly"
                }
              ],
              "note": "Same test, one more day"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Doubling the sample helps, but 2,000 visits each may still be too few for a gap this small.",
              "example": "\"Let's agree on a target number of visits first, then check once.\""
            }
          ],
          "next": "last-check"
        }
      ]
    },
    {
      "id": "explain-result",
      "messages": [
        {
          "from": "data",
          "text": "Now it is 300 sales from 10,000 visits for A and 360 from 10,000 for B. The gap held up as the sample grew."
        },
        {
          "from": "product",
          "text": "B wins. What do I tell the meeting at 3 p.m.?"
        },
        {
          "from": "ai",
          "text": "I can check a plain-words version of the result if you want."
        }
      ],
      "prompt": "What do you tell {{product}} about the test result?",
      "choices": [
        {
          "id": "explain-numbers",
          "text": "Tell {{product}} B sold more in 10,000 visits each, and leave out the part about chance",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "So B is better, right? I need one clear line for the meeting."
            },
            {
              "from": "data",
              "text": "You shared the counts but left out chance, so the message could sound more sure than the test is."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 5
            },
            {
              "meter": "patience",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "You shared the numbers but left out chance, so {{product}} could hear more certainty than the test gives.",
              "example": "\"B was higher in a larger test, and a gap this size is less likely to be just chance.\""
            }
          ],
          "next": "final-call"
        },
        {
          "id": "definite-b",
          "text": "Tell {{product}} B is definitely better for all shoppers and there is no doubt at all",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I will tell the meeting B is a sure win for all shoppers."
            },
            {
              "from": "data",
              "text": "That is too strong. Even a large test cannot give no doubt, and sales still need watching."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "patience",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "You said there is no doubt, but a test never gives that kind of certainty.",
              "example": "\"B looks better in this test, but we should still watch sales after launch.\""
            }
          ],
          "next": "final-call"
        },
        {
          "id": "explain-plain",
          "text": "Tell {{product}} B sold more in 10,000 visits each, and the gap looks unlikely to be just chance",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "I can say that in the meeting: B was higher in a larger test, and chance looks less likely."
            },
            {
              "from": "data",
              "text": "That wording is clear. It gives the counts, the sample size, and the limit."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "patience",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You explained the result with the sample size and what chance could still do.",
              "example": null
            }
          ],
          "next": "final-call"
        }
      ]
    },
    {
      "id": "last-check",
      "messages": [
        {
          "from": "data",
          "text": "We still do not have a large enough sample to trust a gap of 30 versus 34 sales."
        },
        {
          "from": "product",
          "text": "The meeting is today at 3 p.m. Can we just launch B and see what happens?"
        },
        {
          "from": "ai",
          "text": "I can run the chance check and work out a larger sample if you ask me."
        }
      ],
      "prompt": "What do you do before anyone launches button B?",
      "choices": [
        {
          "id": "pause-launch",
          "text": "Pause the launch for now and keep button A while you think it over",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I do not like pausing, but I will keep A live for now."
            },
            {
              "from": "data",
              "text": "Pausing stops a risky launch. We still need a plan for more data."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Pausing stops a risky launch, but without a plan for more data you will still not know if B is better.",
              "example": "\"Let's pause B and set a target of 10,000 visits each before we decide.\""
            }
          ],
          "next": "kept-a"
        },
        {
          "id": "check-and-wait",
          "text": "Ask {{ai}} to run the chance check, then run the test to 10,000 visits each",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "The p-value for 30 versus 34 sales in 1,000 visits each is about 0.61, so this gap could be chance quite often. A larger sample is needed."
            },
            {
              "from": "data",
              "text": "That check confirms we should wait for more visits before we call B the winner."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "patience",
              "change": -15
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "Checkout test · larger sample",
              "metrics": [
                {
                  "label": "Button A sales",
                  "value": "3.0%",
                  "note": "300 sales from 10,000 visits"
                },
                {
                  "label": "Button B sales",
                  "value": "3.6%",
                  "note": "360 sales from 10,000 visits"
                },
                {
                  "label": "Visits per button",
                  "value": "10,000",
                  "note": "visitors split evenly"
                }
              ],
              "note": "Same test, more visits"
            }
          },
          "notes": [
            {
              "skill": "difference",
              "kind": "good",
              "text": "You asked for a check and a larger sample instead of launching on a small gap.",
              "example": null
            }
          ],
          "next": "final-call"
        },
        {
          "id": "launch-anyway",
          "text": "Tell {{product}} to launch button B for everyone even without a check",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I will start the launch now so B is live for everyone."
            },
            {
              "from": "data",
              "text": "Stop. We have not checked if this gap could be chance, so this launch is too risky."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 25
            },
            {
              "meter": "patience",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "difference",
              "kind": "improve",
              "text": "Launching without a check put a possible chance gap in front of all shoppers.",
              "example": "\"Can we check if this gap could be chance before we launch?\""
            }
          ],
          "next": "stopped-launch"
        }
      ]
    },
    {
      "id": "final-call",
      "messages": [
        {
          "from": "product",
          "text": "The 3 p.m. meeting is soon. Should B go live for everyone or not?"
        },
        {
          "from": "data",
          "text": "In the larger test, B had 360 sales in 10,000 visits and A had 300. Say how sure you are and what we watch next."
        }
      ],
      "prompt": "What is your final call on button B?",
      "choices": [
        {
          "id": "keep-a",
          "text": "Keep button A for everyone and drop button B without launching it",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I wanted B live, but I will keep A for now if that is your call."
            },
            {
              "from": "data",
              "text": "Keeping A is safe, but B looked better in 10,000 visits each, so we may miss a real gain."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 10
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "difference",
              "kind": "improve",
              "text": "You kept A even though the larger test showed B ahead, so a real gain could be missed.",
              "example": "\"B was higher in 10,000 visits each; let's launch B and watch sales.\""
            }
          ],
          "next": "kept-a"
        },
        {
          "id": "watch-more",
          "text": "Keep the test running for one more week before you launch B for everyone",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "Another week will make the meeting hard, but I can say the test is still running."
            },
            {
              "from": "data",
              "text": "More data is safe, but the larger test already shows a gap that held up."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "patience",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Waiting more is safe, but the large sample already gives a clear enough signal to act.",
              "example": "\"The gap held up in 10,000 visits each, so let's launch B and watch.\""
            }
          ],
          "next": "kept-testing"
        },
        {
          "id": "launch-b",
          "text": "Launch button B for everyone and keep watching sales each week",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "B will go live for everyone, and I will tell the meeting about the larger test."
            },
            {
              "from": "data",
              "text": "Good call. We will watch weekly sales so we can spot a change fast."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "patience",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "difference",
              "kind": "good",
              "text": "You made the call only after a large sample showed a gap that held up.",
              "example": null
            }
          ],
          "next": "launched-b"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "launched-b",
      "outcome": "Button B went to everyone: A was 3.0% and B was 3.6% in 10,000 visits each, so B had 60 more sales in the larger test."
    },
    {
      "id": "kept-testing",
      "outcome": "The test kept running instead of launching B, so shoppers stayed split between A at 3.0% and B at 3.6% in 10,000 visits each."
    },
    {
      "id": "kept-a",
      "outcome": "Button A stayed live for everyone and button B did not launch. You can test B again later with a larger sample."
    },
    {
      "id": "stopped-launch",
      "outcome": "Button B did not go live. {{data}} stopped the launch before shoppers saw it, and the test stayed on A at 3.0% while you plan a larger sample."
    }
  ],
  "summary": [
    "A higher number in a small test can still be chance, so check the gap before you act.",
    "A larger sample makes a real gap easier to tell from chance.",
    "Explain a test result in plain words, including how much chance could still matter."
  ]
}

{
  "title": "E se a luz viesse em pacotinhos?",
  "setting": "Noite de experimentos em casa",
  "mission": "Você usa uma lâmpada especial que pode ficar bem fraquinha. Descubra **o que acontece com a luz quando ela quase apaga**.",
  "deadline": null,
  "panels": [],
  "team": [
    {
      "id": "curiosa",
      "role": "Pesquisadora amadora",
      "expertise": "Faz perguntas e anota o que vê durante o experimento",
      "ai": false
    },
    {
      "id": "tecnico",
      "role": "Técnico da oficina",
      "expertise": "Monta e ajusta a lâmpada e os sensores do experimento",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "curiosity",
      "label": "Curiosidade acesa",
      "start": 40,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "energy-packets",
      "name": "Energia vem em pacotes",
      "practice": "Explique em uma frase, usando gotinhas, por que a luz fraquinha ainda chega em pacotinhos."
    },
    {
      "id": "wave-particle",
      "name": "Luz é onda e bolinha",
      "practice": "Conte em uma frase quando a luz parece bolinha e quando parece onda."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "curiosa",
          "text": "Que lâmpada maluca! Ela pode ficar bem fraquinha, quase apagada. Dizem que a luz dela vem em pacotinhos, os quanta."
        },
        {
          "from": "tecnico",
          "text": "Eu consigo deixar ela bem fraquinha. Mas não sei se ela vai ficar só menos brilhante ou se vai vir em bolinhas bem espaçadas."
        }
      ],
      "prompt": "O que você quer experimentar primeiro?",
      "choices": [
        {
          "id": "just-watch",
          "text": "Deixar a lâmpada fraquinha e só observar se ela parece mais apagada",
          "quality": "fair",
          "replies": [
            {
              "from": "curiosa",
              "text": "Ela fica bem apagadinha, sim. Mas, sem contar, não sei se a luz virou pacotinhos menores ou só chegaram menos pacotinhos."
            }
          ],
